sp_widget.client_script:
api.controller = function($scope, $location) {

  /* =========================================================
     GATENOW · COMPLETED REVIEWS · Client script

     Page: review_completed

     The mirror of the review_applicants controller. Same
     helpers, same names, same shapes — with one line inverted:

       review_applicants   if (r.status === 'Review completed') return false;
       review_completed    if (r.status !== 'Review completed') return false;

     That is the whole difference between the two pages. The
     server is the same script on both, so one query feeds
     both lists and they can never disagree about a review.

     Escalated and declined reviews are not here. They are not
     completed work, and counting them would make the average
     score the average of something else.

     openRecord and scoreWidth are the uploaded controller's,
     unchanged. Nothing writes to window.location: every
     destination is either $location.search or an anchor.
     ========================================================= */

  var c = this;

  c.searchText     = '';
  c.bandFilter     = '';
  c.categoryFilter = '';
  c.programFilter  = '';
  c.sortBy         = 'recent';

  c.proposalPage = 1;
  c.pageSize     = 12;

  $scope.$watchGroup(
    ['c.searchText', 'c.bandFilter', 'c.categoryFilter', 'c.programFilter'],
    function() {
      c.proposalPage = 1;
    }
  );


  /* =====================================================
     THE BASE LIST

     Every completed review in data, which is the set the
     uploaded controller's completedReviews() returned. All
     counting and filtering below works from this.
     ===================================================== */

  c.completedReviews = function() {
    return (c.data.reviews || []).filter(function(r) {
      return r.status === 'Review completed';
    });
  };

  /* the same 7 and 4 thresholds the scoring control on the
     proposal page uses, so no two screens disagree about what
     a 7 means */
  c.bandOf = function(score) {
    var n = parseInt(score, 10);
    if (!score || isNaN(n)) return 'none';
    if (n >= 7) return 'high';
    if (n >= 4) return 'mid';
    return 'low';
  };


  /* =====================================================
     FACETS

     Built from the completed rows rather than from a choice
     table. A program this reviewer's panels never finished
     should not appear in their filter, and one that exists
     only in their data should.
     ===================================================== */

  c.categoryOptions = function() {

    var seen = {}, opts = [];

    c.completedReviews().forEach(function(r) {
      if (r.program_category && !seen[r.program_category]) {
        seen[r.program_category] = true;
        opts.push(r.program_category);
      }
    });

    return opts.sort();
  };

  c.programOptions = function() {

    var seen = {}, opts = [];

    c.completedReviews().forEach(function(r) {
      if (r.program && !seen[r.program]) {
        seen[r.program] = true;
        opts.push(r.program);
      }
    });

    return opts.sort();
  };

  /* status is fixed on this page, so the chips that would have
     carried it carry the score band instead — the one axis a
     finished list is actually read along */
  c.bands = [
    { key: '',     label: 'Every score' },
    { key: 'high', label: 'Strong, 7 to 10' },
    { key: 'mid',  label: 'Moderate, 4 to 6' },
    { key: 'low',  label: 'Weak, 1 to 3' },
    { key: 'none', label: 'Not scored' }
  ];

  c.bandCount = function(key) {
    var all = c.completedReviews();
    if (!key) return all.length;
    return all.filter(function(r) { return c.bandOf(r.score) === key; }).length;
  };

  c.sorts = [
    { key: 'recent',    label: 'Reference, newest first' },
    { key: 'oldest',    label: 'Reference, oldest first' },
    { key: 'scoreHigh', label: 'Score, highest first' },
    { key: 'scoreLow',  label: 'Score, lowest first' },
    { key: 'applicant', label: 'Applicant, A to Z' },
    { key: 'program',   label: 'Program, A to Z' }
  ];


  /* =====================================================
     FILTERING

     The mirror of filteredProposals. Same structure, same
     search across the same four fields, with the status test
     inverted and the score band in place of the status
     filter.
     ===================================================== */

  function lower(v) { return (v || '').toLowerCase(); }

  function comparator(k) {

    if (k === 'oldest') {
      return function(a, b) { return lower(a.number) < lower(b.number) ? -1 : 1; };
    }

    if (k === 'scoreHigh') {
      return function(a, b) {
        return (parseInt(b.score, 10) || -1) - (parseInt(a.score, 10) || -1);
      };
    }

    if (k === 'scoreLow') {
      /* unscored rows sort last on ascending too. No score is
         an absence, not a low score, and putting them first
         would bury every real low score. */
      return function(a, b) {
        var x = parseInt(a.score, 10);
        var y = parseInt(b.score, 10);
        if (isNaN(x) && isNaN(y)) return 0;
        if (isNaN(x)) return 1;
        if (isNaN(y)) return -1;
        return x - y;
      };
    }

    if (k === 'applicant') {
      return function(a, b) { return lower(a.applicant) < lower(b.applicant) ? -1 : 1; };
    }

    if (k === 'program') {
      return function(a, b) { return lower(a.program) < lower(b.program) ? -1 : 1; };
    }

    return function(a, b) { return lower(a.number) < lower(b.number) ? 1 : -1; };
  }

  c.filteredProposals = function() {

    var out = c.completedReviews().filter(function(r) {

      if (c.bandFilter && c.bandOf(r.score) !== c.bandFilter) return false;
      if (c.categoryFilter && r.program_category !== c.categoryFilter) return false;
      if (c.programFilter && r.program !== c.programFilter) return false;

      if (c.searchText) {

        var txt = c.searchText.toLowerCase();

        if (
          (r.number || '').toLowerCase().indexOf(txt) === -1 &&
          (r.program || '').toLowerCase().indexOf(txt) === -1 &&
          (r.applicant || '').toLowerCase().indexOf(txt) === -1 &&
          (r.program_category || '').toLowerCase().indexOf(txt) === -1
        ) {
          return false;
        }
      }

      return true;
    });

    /* slice before sort: sort mutates, and completedReviews
       already returns a new array, but the habit is what stops
       the day somebody makes it return the original */
    return out.slice().sort(comparator(c.sortBy));
  };


  /* =====================================================
     WHAT THEY ADD UP TO

     Three figures and a distribution, all counted from the
     same filtered set the list shows. When a filter narrows
     the list, the figures narrow with it — a summary that
     describes a different set from the rows underneath is
     worse than no summary.
     ===================================================== */

  c.summary = function() {

    var rows = c.filteredProposals();

    var sum = 0, scored = 0;
    var band = { high: 0, mid: 0, low: 0, none: 0 };
    var dist = [];
    var i;

    for (i = 0; i < 10; i++) dist.push(0);

    for (i = 0; i < rows.length; i++) {

      var n = parseInt(rows[i].score, 10);
      var b = c.bandOf(rows[i].score);
      band[b]++;

      if (!isNaN(n)) {
        scored++;
        sum += n;
        if (n >= 1 && n <= 10) dist[n - 1]++;
      }
    }

    var peak = 0;
    for (i = 0; i < dist.length; i++) if (dist[i] > peak) peak = dist[i];

    var bars = [];
    for (i = 0; i < 10; i++) {
      bars.push({
        n    : i + 1,
        count: dist[i],
        /* measured against the tallest column so the shape is
           readable even when every count is small */
        pct  : peak > 0 ? Math.round((dist[i] / peak) * 100) : 0,
        band : (i + 1) >= 7 ? 'high' : ((i + 1) >= 4 ? 'mid' : 'low')
      });
    }

    return {
      total : rows.length,
      scored: scored,
      avg   : scored ? (Math.round((sum / scored) * 10) / 10) : null,
      band  : band,
      bars  : bars
    };
  };

  c.headline = function() {

    var s = c.summary();

    if (!c.completedReviews().length) return 'Nothing finished yet';

    var out = s.total + (s.total === 1 ? ' completed review' : ' completed reviews');
    if (s.avg !== null) out += ' · averaging ' + s.avg + ' out of 10';
    return out;
  };

  c.isFiltered = function() {
    return !!(c.searchText || c.bandFilter || c.categoryFilter || c.programFilter);
  };

  c.clearFilters = function() {
    c.searchText     = '';
    c.bandFilter     = '';
    c.categoryFilter = '';
    c.programFilter  = '';
  };


  /* =====================================================
     PAGING

     The uploaded controller's, unchanged.
     ===================================================== */

  c.pagedProposals = function() {

    var all   = c.filteredProposals();
    var start = (c.proposalPage - 1) * c.pageSize;

    return all.slice(start, start + c.pageSize);
  };

  c.totalPages = function() {
    return Math.ceil(c.filteredProposals().length / c.pageSize) || 1;
  };

  c.pageNumbers = function() {

    var total   = c.totalPages();
    var current = c.proposalPage;
    var pages   = [];

    var start = Math.max(1, current - 2);
    var end   = Math.min(total, current + 2);

    if (start > 1) pages.push(1);
    if (start > 2) pages.push('...');

    for (var i = start; i <= end; i++) pages.push(i);

    if (end < total - 1) pages.push('...');
    if (end < total) pages.push(total);

    return pages;
  };

  c.goToPage = function(p) {
    if (p !== '...' && p >= 1 && p <= c.totalPages()) c.proposalPage = p;
  };

  c.prevPage = function() {
    if (c.proposalPage > 1) c.proposalPage--;
  };

  c.nextPage = function() {
    if (c.proposalPage < c.totalPages()) c.proposalPage++;
  };


  /* =====================================================
     OPENING

     A finished review still opens on the proposal page, which
     shows it locked and leaves the notes open. There is no
     separate read-only view to build or maintain.
     ===================================================== */

  c.openRecord = function(rev) {

    if (!rev || !rev['sys_id']) return;

    $location.search({
      id: 'review_proposal_detail_page',
      sys_id: rev['sys_id']
    });
  };

  c.scoreWidth = function(score) {
    if (!score) return '0%';
    return Math.min(Math.round((parseInt(score, 10) / 10) * 100), 100) + '%';
  };

  /* the uploaded controller's chip mapping, kept so a status
     chip means the same thing on every reviewer page */
  c.statusChipClass = function(status) {
    if (status === 'Review completed') return 'rvd-chip--green';
    if (status === 'Escalated') return 'rvd-chip--red';
    if (status === 'Declined by Reviewer') return 'rvd-chip--rose';
    if (status === 'Review pending') return 'rvd-chip--slate';
    return 'rvd-chip--amber';
  };
};

sp_widget.css:
/* =========================================================
   GATENOW · COMPLETED REVIEWS
   Service Portal widget · CSS / SCSS

   Page: review_completed

   Written with fully expanded selectors on purpose.
   The Service Portal Sass compiler does not support parent
   selector concatenation (&__head, &--green), so every rule
   below is written out in full.

   ── RELATIONSHIP TO THE PORTAL ────────────────────────────

   The token block and every shared component are the applicant
   Overview's, unchanged: Poppins, indigo #4457c9, ink #16203a,
   the 16px radius, the two-layer shadow, gn-head, gn-card,
   gn-table, gn-btn.

   ── WHAT THIS PAGE ADDS ───────────────────────────────────

   A finished list is read differently from an open one. Nobody
   opens their completed reviews to find out what to do next;
   they open them to see how their panels have been scoring.

   So the additions are all about the score: three figures, a
   distribution on the same ten-point grid the scoring control
   uses, band-coloured scores in the rows, and chips that
   filter by band rather than by status — status being fixed on
   this page and therefore a control that could not change
   anything.
   ========================================================= */

$gn-bg:          #f4f6fb;
$gn-card:        #ffffff;
$gn-line:        #e7eaf2;
$gn-line-soft:   #eff2f7;

$gn-ink:         #16203a;
$gn-ink-2:       #3f4a63;
$gn-muted:       #7b8598;
$gn-muted-2:     #9aa3b4;

$gn-indigo:      #4457c9;
$gn-indigo-dk:   #3a4bb3;
$gn-indigo-mid:  #7b90ee;
$gn-indigo-soft: #aebcf5;
$gn-violet:      #6f5fd0;
$gn-green:       #1f9d6d;
$gn-sage:        #93c8ae;
$gn-amber:       #e2a233;
$gn-red:         #e0525f;
$gn-slate:       #c9d2e3;

$gn-font: "Poppins", "Inter", "Segoe UI", -apple-system, BlinkMacSystemFont, Arial, sans-serif;


/* =========================================================
   SHELL
   ========================================================= */

/* Service Portal wraps every widget in a panel that clips
   anything leaving its box, which cuts the rail tooltips off
   at the column edge. */
.panel,
.panel-body,
.sp-widget { overflow: visible !important; }

.gn-layout.gn-p-completed {
  display: flex;
  align-items: stretch;
  min-height: 100vh;
  overflow: visible !important;
}

.gn-p-completed .aw-sidebar {
  flex: 0 0 auto;
  position: sticky;
  top: 0;
  height: 100vh;
  z-index: 10;
  overflow: visible;
}

/* Without min-width: 0 a flex child refuses to shrink below
   its own content width, and slides under the rail rather
   than narrowing. */
.gn-p-completed .gn-dash {
  flex: 1;
  min-width: 0;
  overflow: visible;
  background: $gn-bg;
  font-family: $gn-font;
  color: $gn-ink;
  padding: 26px 30px 46px;
  min-height: 100vh;
}

.gn-p-completed .gn-dash *,
.gn-p-completed .gn-dash *::before,
.gn-p-completed .gn-dash *::after { box-sizing: border-box; }

.gn-p-completed .gn-dash h1,
.gn-p-completed .gn-dash h2,
.gn-p-completed .gn-dash p { margin: 0; }

.gn-p-completed .gn-dash a { text-decoration: none; }
.gn-p-completed .gn-dash a:hover,
.gn-p-completed .gn-dash a:focus { text-decoration: none; }

.gn-p-completed .gn-dash :focus-visible {
  outline: 2px solid $gn-indigo;
  outline-offset: 2px;
}


/* =========================================================
   HEADER
   ========================================================= */

.gn-p-completed .gn-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 22px;
}

.gn-p-completed .gn-head__left { min-width: 0; }

.gn-p-completed .gn-head__title {
  font-size: 30px;
  font-weight: 600;
  letter-spacing: -0.6px;
  line-height: 1.15;
  color: $gn-ink;
}

.gn-p-completed .gn-head__meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 6px;
  font-size: 12.5px;
  color: $gn-muted;
}

.gn-p-completed .gn-head__right {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.gn-p-completed .gn-live {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: $gn-green;
  flex-shrink: 0;
}

.gn-p-completed .gn-avatar {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: $gn-indigo;
  color: #ffffff;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.3px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}


/* =========================================================
   KPI CARDS
   ========================================================= */

.gn-p-completed .gn-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 20px;
  margin-bottom: 20px;
}

/* Portal columns are narrower than the viewport, so the grid
   also reflows on its own container width, not just on media
   queries. */
@supports (grid-template-columns: repeat(auto-fit, minmax(220px, 1fr))) {
  .gn-p-completed .gn-kpis { grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); }
}

.gn-p-completed .gn-kpi {
  display: flex;
  flex-direction: column;
  background: $gn-card;
  border: 1px solid $gn-line;
  border-radius: 16px;
  padding: 20px 22px 16px;
  min-height: 212px;
  box-shadow: 0 1px 2px rgba(22, 32, 58, 0.04), 0 8px 20px rgba(22, 32, 58, 0.04);
}

.gn-p-completed .gn-kpi__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.gn-p-completed .gn-kpi__label {
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  color: $gn-muted;
}

.gn-p-completed .gn-kpi__icon {
  width: 32px;
  height: 32px;
  border-radius: 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  flex-shrink: 0;
}

.gn-p-completed .gn-kpi__icon--indigo { color: $gn-indigo; background: #edf1ff; }
.gn-p-completed .gn-kpi__icon--violet { color: $gn-violet; background: #f0edfd; }
.gn-p-completed .gn-kpi__icon--amber { color: #c98a1c;    background: #fdf4e2; }

.gn-p-completed .gn-kpi__figure {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 14px;
}

.gn-p-completed .gn-kpi__value {
  font-size: 38px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: -1.4px;
  color: $gn-ink;
}

.gn-p-completed .gn-kpi__desc {
  margin-top: 10px;
  font-size: 12.5px;
  line-height: 1.55;
  color: $gn-muted;
}

.gn-p-completed .gn-kpi__caption {
  margin-top: auto;
  padding-top: 10px;
  font-size: 11px;
  color: $gn-muted-2;
}


/* ---------- chips ---------- */

.gn-p-completed .gn-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 500;
  white-space: nowrap;
  background: #f1f3f8;
  color: $gn-ink-2;
}

.gn-p-completed .gn-chip--green { background: #e6f6ef; color: #178a5e; }
.gn-p-completed .gn-chip--amber { background: #fdf1dd; color: #b9801a; }
.gn-p-completed .gn-chip--red { background: #fdecee; color: #cf4351; }


/* ---------- sparkline ---------- */

.gn-p-completed .gn-spark {
  position: relative;
  height: 34px;
  margin-top: 16px;
}

.gn-p-completed .gn-spark svg {
  width: 100%;
  height: 100%;
  display: block;
  overflow: visible;
}

.gn-p-completed .gn-spark__line {
  fill: none;
  stroke-width: 2;
  stroke-linejoin: round;
  stroke-linecap: round;
  vector-effect: non-scaling-stroke;
}

.gn-p-completed .gn-spark__area {
  stroke: none;
  fill: rgba(68, 87, 201, 0.10);
}

.gn-p-completed .gn-spark__dot {
  position: absolute;
  right: 0;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  transform: translate(1px, -50%);
  background: $gn-indigo;
}

.gn-p-completed .gn-spark--indigo .gn-spark__line { stroke: $gn-indigo; }
.gn-p-completed .gn-spark--indigo .gn-spark__area { fill: rgba(68, 87, 201, 0.10); }
.gn-p-completed .gn-spark--indigo .gn-spark__dot { background: $gn-indigo; }

.gn-p-completed .gn-spark--green .gn-spark__line { stroke: $gn-green; }
.gn-p-completed .gn-spark--green .gn-spark__area { fill: rgba(31, 157, 109, 0.12); }
.gn-p-completed .gn-spark--green .gn-spark__dot { background: $gn-green; }


/* ---------- milestone bars ---------- */

.gn-p-completed .gn-milestones {
  display: flex;
  align-items: flex-end;
  gap: 5px;
  height: 34px;
  margin-top: 16px;
}

.gn-p-completed .gn-milestone {
  flex: 1;
  min-height: 30%;
  border-radius: 4px;
  background: #dde3f5;
  transition: height 0.4s ease;
}

.gn-p-completed .gn-milestone.is-current { background: $gn-indigo; }


/* ---------- segmented bar ---------- */

.gn-p-completed .gn-segbar {
  display: flex;
  height: 7px;
  margin-top: 22px;
  border-radius: 999px;
  overflow: hidden;
  background: #e9edf4;
}

.gn-p-completed .gn-seg { height: 100%; transition: width 0.4s ease; }
.gn-p-completed .gn-seg--red { background: $gn-red; }
.gn-p-completed .gn-seg--amber { background: $gn-amber; }
.gn-p-completed .gn-seg--grey { background: #dfe4ee; }


/* =========================================================
   CARD SYSTEM
   ========================================================= */

.gn-p-completed .gn-row {
  display: grid;
  gap: 20px;
  margin-bottom: 20px;
}

.gn-p-completed .gn-row--wide {
  grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);
}

.gn-p-completed .gn-card {
  display: flex;
  flex-direction: column;
  background: $gn-card;
  border: 1px solid $gn-line;
  border-radius: 16px;
  box-shadow: 0 1px 2px rgba(22, 32, 58, 0.04), 0 8px 20px rgba(22, 32, 58, 0.04);
  min-width: 0;
  overflow: hidden;
}

.gn-p-completed .gn-card__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 24px 4px;
}

.gn-p-completed .gn-card__head h2 {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.2px;
  line-height: 1.3;
  color: $gn-ink;
}

.gn-p-completed .gn-card__head p {
  margin-top: 4px;
  font-size: 12.5px;
  color: $gn-muted;
}

.gn-p-completed .gn-card__body {
  padding: 18px 24px 22px;
  flex: 1;
}

.gn-p-completed .gn-card__body--tight { padding: 12px 16px 16px; }

.gn-p-completed .gn-card__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 0 24px;
  padding: 14px 0 18px;
  border-top: 1px solid $gn-line-soft;
  font-size: 12px;
  color: $gn-muted;
}

.gn-p-completed .gn-link {
  color: $gn-indigo;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
}

.gn-p-completed .gn-link:hover { color: $gn-indigo-dk; }

.gn-p-completed .gn-note {
  padding-top: 16px;
  margin-top: 16px;
  border-top: 1px solid $gn-line-soft;
  font-size: 12px;
  line-height: 1.5;
  color: $gn-muted-2;
}

.gn-p-completed .gn-empty {
  padding: 34px 12px;
  text-align: center;
  font-size: 12.5px;
  line-height: 1.6;
  color: $gn-muted-2;
}

.gn-p-completed .gn-total {
  text-align: right;
  flex-shrink: 0;
}

.gn-p-completed .gn-total strong {
  display: block;
  font-size: 21px;
  font-weight: 600;
  letter-spacing: -0.5px;
  color: $gn-ink;
}

.gn-p-completed .gn-total span {
  font-size: 11px;
  color: $gn-muted-2;
}


/* =========================================================
   CHARTS
   ========================================================= */

.gn-p-completed .gn-chart {
  display: flex;
  gap: 12px;
}

.gn-p-completed .gn-chart__axis {
  width: 22px;
  height: 220px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: flex-end;
  font-size: 11px;
  line-height: 1;
  color: $gn-muted-2;
  flex-shrink: 0;
}

.gn-p-completed .gn-chart__plot {
  position: relative;
  flex: 1;
  height: 220px;
  min-width: 0;
}

.gn-p-completed .gn-grid {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.gn-p-completed .gn-grid__line {
  display: block;
  width: 100%;
  height: 1px;
  background: $gn-line-soft;
}

.gn-p-completed .gn-grid__line:last-child { background: $gn-line; }

.gn-p-completed .gn-cols {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  display: flex;
  align-items: flex-end;
  justify-content: space-around;
  gap: 10px;
}

.gn-p-completed .gn-col {
  position: relative;
  flex: 1;
  min-width: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
}

.gn-p-completed .gn-col__track {
  width: 62px;
  max-width: 72%;
  flex: 1;
  display: flex;
  align-items: flex-end;
}

.gn-p-completed .gn-col__bar {
  position: relative;
  width: 100%;
  min-height: 3px;
  border-radius: 6px 6px 0 0;
  background: $gn-indigo-soft;
  transition: height 0.45s ease;
}

.gn-p-completed .gn-col__value {
  position: absolute;
  bottom: 100%;
  left: 0;
  right: 0;
  margin-bottom: 7px;
  text-align: center;
  font-size: 12px;
  font-weight: 600;
  color: $gn-ink-2;
}

.gn-p-completed .gn-col__cluster {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 5px;
  width: 100%;
  height: 100%;
}

.gn-p-completed .gn-gbar {
  width: 14px;
  min-height: 2px;
  border-radius: 4px 4px 0 0;
  transition: height 0.45s ease;
}

.gn-p-completed .gn-gbar--indigo { background: $gn-indigo; }
.gn-p-completed .gn-gbar--periwinkle { background: $gn-indigo-mid; }
.gn-p-completed .gn-gbar--sage { background: $gn-sage; }

.gn-p-completed .gn-tip {
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translate(-50%, 2px);
  min-width: 150px;
  padding: 8px 11px;
  border-radius: 9px;
  background: $gn-ink;
  color: #ffffff;
  font-size: 11px;
  line-height: 1.5;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.18s ease, transform 0.18s ease;
  z-index: 5;
}

.gn-p-completed .gn-tip strong {
  display: block;
  font-weight: 600;
}

.gn-p-completed .gn-col:hover .gn-tip {
  opacity: 1;
  transform: translate(-50%, -6px);
}

.gn-p-completed .gn-labels {
  display: flex;
  justify-content: space-around;
  gap: 10px;
  padding-left: 34px;
  margin-top: 10px;
}

.gn-p-completed .gn-labels span {
  flex: 1;
  text-align: center;
  font-size: 12px;
  color: $gn-ink-2;
}

.gn-p-completed .gn-keys {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 16px;
  max-width: 300px;
  font-size: 12px;
  color: $gn-ink-2;
}

.gn-p-completed .gn-keys span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.gn-p-completed .gn-key {
  width: 9px;
  height: 9px;
  border-radius: 3px;
  flex-shrink: 0;
}

.gn-p-completed .gn-key--indigo { background: $gn-indigo; }
.gn-p-completed .gn-key--periwinkle { background: $gn-indigo-mid; }
.gn-p-completed .gn-key--sage { background: $gn-sage; }


/* =========================================================
   HEALTH AND LISTS
   ========================================================= */

.gn-p-completed .gn-health {
  display: flex;
  height: 46px;
  border-radius: 12px;
  overflow: hidden;
  background: #eef1f6;
  color: #ffffff;
  font-size: 13px;
  font-weight: 500;
}

.gn-p-completed .gn-health__seg {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 42px;
  white-space: nowrap;
  transition: width 0.45s ease;
}

.gn-p-completed .gn-health__seg--green { background: #1f9d6d; }
.gn-p-completed .gn-health__seg--amber { background: #dfa227; }
.gn-p-completed .gn-health__seg--red { background: $gn-red; }

.gn-p-completed .gn-health__rest {
  flex: 1;
  min-width: 52px;
  padding: 0 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: $gn-muted;
  font-size: 12.5px;
}

.gn-p-completed .gn-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
  padding-bottom: 18px;
  border-bottom: 1px solid $gn-line-soft;
}

.gn-p-completed .gn-legend__pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 5px 11px;
  border-radius: 999px;
  background: #f4f6fa;
  font-size: 12px;
  color: $gn-ink-2;
}

.gn-p-completed .gn-dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
  background: $gn-slate;
}

.gn-p-completed .gn-dot--green { background: $gn-green; }
.gn-p-completed .gn-dot--amber { background: $gn-amber; }
.gn-p-completed .gn-dot--red { background: $gn-red; }

.gn-p-completed .gn-projects { padding-top: 6px; }

.gn-p-completed .gn-project {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 6px 12px;
  padding: 14px 0 10px;
  border-bottom: 1px solid $gn-line-soft;
}

.gn-p-completed .gn-project:last-child { border-bottom: 0; }

.gn-p-completed .gn-project__name {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  font-size: 13.5px;
  font-weight: 500;
  color: $gn-ink;
}

.gn-p-completed .gn-project__name span {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.gn-p-completed .gn-project__pct {
  font-size: 13px;
  color: $gn-ink-2;
  white-space: nowrap;
}

.gn-p-completed .gn-project__track {
  grid-column: 1 / -1;
  height: 5px;
  border-radius: 999px;
  background: #edf0f6;
  overflow: hidden;
}

.gn-p-completed .gn-project__fill {
  height: 100%;
  border-radius: 999px;
  background: $gn-slate;
  transition: width 0.45s ease;
}

.gn-p-completed .gn-project__fill--green { background: $gn-green; }
.gn-p-completed .gn-project__fill--amber { background: $gn-amber; }
.gn-p-completed .gn-project__fill--red { background: $gn-red; }


/* =========================================================
   CLAIM BARS
   ========================================================= */

.gn-p-completed .gn-claim { margin-bottom: 18px; }
.gn-p-completed .gn-claim:last-child { margin-bottom: 0; }

.gn-p-completed .gn-claim__meta {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
}

.gn-p-completed .gn-claim__label {
  font-size: 13.5px;
  font-weight: 500;
  color: $gn-ink;
}

.gn-p-completed .gn-claim__value {
  font-size: 12.5px;
  color: $gn-muted;
}

.gn-p-completed .gn-claim__track {
  height: 8px;
  border-radius: 999px;
  background: #edf0f6;
  overflow: hidden;
}

.gn-p-completed .gn-claim__fill {
  height: 100%;
  border-radius: 999px;
  background: $gn-indigo-soft;
  transition: width 0.45s ease;
}

.gn-p-completed .gn-claim__fill--green { background: $gn-green; }
.gn-p-completed .gn-claim__fill--indigo { background: $gn-indigo; }
.gn-p-completed .gn-claim__fill--periwinkle { background: $gn-indigo-mid; }
.gn-p-completed .gn-claim__fill--soft { background: $gn-indigo-soft; }
.gn-p-completed .gn-claim__fill--amber { background: $gn-amber; }
.gn-p-completed .gn-claim__fill--red { background: $gn-red; }


/* =========================================================
   TABLE
   ========================================================= */

.gn-p-completed .gn-table {
  width: 100%;
  margin-top: 14px;
}

.gn-p-completed .gn-table__head,
.gn-p-completed .gn-table__row {
  display: grid;
  grid-template-columns: 1.1fr 1.2fr 1.4fr 1.1fr 1.2fr 0.85fr;
  align-items: center;
  gap: 12px;
  padding: 0 24px;
}

.gn-p-completed .gn-table__head {
  height: 40px;
  background: #f7f9fc;
  border-top: 1px solid $gn-line-soft;
  border-bottom: 1px solid $gn-line-soft;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.7px;
  text-transform: uppercase;
  color: $gn-muted;
}

.gn-p-completed .gn-table__row {
  min-height: 66px;
  padding-top: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid $gn-line-soft;
}

.gn-p-completed .gn-table__row:last-child { border-bottom: 0; }
.gn-p-completed .gn-table__row:hover { background: #fafbfe; }

.gn-p-completed .gn-cell {
  font-size: 13px;
  min-width: 0;
}

.gn-p-completed .gn-cell--name {
  font-weight: 500;
  color: $gn-ink;
  line-height: 1.4;
}

.gn-p-completed .gn-cell--related {
  color: $gn-indigo;
  line-height: 1.4;
}

.gn-p-completed .gn-cell--date {
  color: $gn-ink-2;
  line-height: 1.4;
}

.gn-p-completed .gn-tag {
  display: inline-flex;
  padding: 4px 9px;
  border-radius: 7px;
  background: #edf1ff;
  color: $gn-indigo;
  font-size: 11.5px;
  font-weight: 500;
  white-space: nowrap;
}

.gn-p-completed .gn-state {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border-radius: 999px;
  background: #f2f4f8;
  color: $gn-ink-2;
  font-size: 11.5px;
  font-weight: 500;
  white-space: nowrap;
}

.gn-p-completed .gn-state--red { background: #fdecee; color: #cf4351; }
.gn-p-completed .gn-state--amber { background: #fdf3e0; color: #b9801a; }
.gn-p-completed .gn-state--green { background: #e6f6ef; color: #178a5e; }
.gn-p-completed .gn-state--grey { background: #f2f4f8; color: $gn-muted; }

.gn-p-completed .gn-state--red .gn-dot { background: $gn-red; }
.gn-p-completed .gn-state--amber .gn-dot { background: $gn-amber; }
.gn-p-completed .gn-state--green .gn-dot { background: $gn-green; }
.gn-p-completed .gn-state--grey .gn-dot { background: $gn-muted-2; }

.gn-p-completed .gn-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 74px;
  height: 34px;
  padding: 0 14px;
  border: 1px solid $gn-line;
  border-radius: 9px;
  background: $gn-card;
  color: $gn-ink-2;
  font-size: 12.5px;
  font-weight: 500;
}

.gn-p-completed .gn-btn:hover {
  border-color: $gn-indigo-soft;
  color: $gn-indigo;
}

.gn-p-completed .gn-btn--primary {
  background: $gn-indigo;
  border-color: $gn-indigo;
  color: #ffffff;
}

.gn-p-completed .gn-btn--primary:hover {
  background: $gn-indigo-dk;
  border-color: $gn-indigo-dk;
  color: #ffffff;
}


/* =========================================================
   PROGRAM CARDS
   ========================================================= */

.gn-p-completed .gn-program {
  display: block;
  padding: 16px 18px;
  margin-bottom: 12px;
  border: 1px solid $gn-line;
  border-radius: 12px;
  color: inherit;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.gn-p-completed .gn-program:last-child { margin-bottom: 0; }

.gn-p-completed .gn-program:hover {
  border-color: $gn-indigo-soft;
  box-shadow: 0 6px 16px rgba(22, 32, 58, 0.06);
}

.gn-p-completed .gn-program__top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.gn-p-completed .gn-program__top strong {
  font-size: 14px;
  font-weight: 600;
  color: $gn-ink;
}

.gn-p-completed .gn-program__desc {
  margin-top: 8px;
  font-size: 12.5px;
  line-height: 1.55;
  color: $gn-indigo;
}

.gn-p-completed .gn-program__foot {
  margin-top: 12px;
  font-size: 12px;
  color: $gn-muted;
}

.gn-p-completed .gn-program__foot i { margin-right: 6px; }


/* =========================================================
   THE rvd- CHIP

   Still named by the controller's statusChipClass(), kept so a
   status chip means the same thing on every reviewer page.
   Only green is reachable here, but all five stay defined:
   deleting the other four would break the moment somebody
   widened the filter.
   ========================================================= */

.gn-p-completed .rvd-chip {
  display: inline-flex;
  align-items: center;
  padding: 5px 11px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 500;
  white-space: nowrap;
  background: #f2f4f8;
  color: $gn-ink-2;
}

.gn-p-completed .rvd-chip--amber { background: #fdf3e0; color: #b9801a; }
.gn-p-completed .rvd-chip--green { background: #e6f6ef; color: #178a5e; }
.gn-p-completed .rvd-chip--red { background: #fdecee; color: #cf4351; }
.gn-p-completed .rvd-chip--rose { background: #fbeef0; color: #b0616d; }
.gn-p-completed .rvd-chip--slate { background: #f2f4f8; color: $gn-muted; }


/* =========================================================
   THE SUMMARY
   ========================================================= */

.gn-p-completed .gnc-sum {
  flex-direction: row;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 32px;
  padding: 22px 24px;
  margin-bottom: 20px;
}

.gn-p-completed .gnc-figs {
  display: flex;
  align-items: stretch;
  flex: 0 0 auto;
}

.gn-p-completed .gnc-fig {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 2px 26px;
  border-left: 1px solid $gn-line-soft;
  min-width: 0;
}

.gn-p-completed .gnc-fig:first-child {
  border-left: 0;
  padding-left: 0;
}

.gn-p-completed .gnc-fig__n {
  display: flex;
  align-items: baseline;
  gap: 7px;
  font-size: 28px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.9px;
  color: $gn-ink;
}

/* the denominator at caption weight. "7.4" and "7.4 out of 10"
   are different claims and only the second one is true. */
.gn-p-completed .gnc-fig__of {
  font-size: 12.5px;
  font-weight: 400;
  letter-spacing: 0;
  color: $gn-muted;
}

.gn-p-completed .gnc-fig__l {
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  color: $gn-muted;
  white-space: nowrap;
}


/* ---------- the distribution ----------

   Ten columns on the same grid as the control that produced
   them, so a panel's habits read against a scale the reviewer
   already has in hand.
   ------------------------------------------------------- */

.gn-p-completed .gnc-spread {
  flex: 1 1 320px;
  min-width: 260px;
}

.gn-p-completed .gnc-spread__h {
  margin: 0 0 12px;
  font-size: 12.5px;
  color: $gn-muted;
}

.gn-p-completed .gnc-spread__grid {
  display: grid;
  grid-template-columns: repeat(10, minmax(0, 1fr));
  align-items: end;
  gap: 5px;
  height: 72px;
}

.gn-p-completed .gnc-col {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-end;
  height: 100%;
  min-width: 0;
}

/* columns grow from the baseline, which is the only direction
   a column chart can grow from without looking wrong */
.gn-p-completed .gnc-col__bar {
  display: block;
  border-radius: 4px 4px 0 0;
  transform-origin: center bottom;
  transition: height 0.4s ease;
}

/* the same 7 and 4 thresholds the scoring control uses, so no
   two screens disagree about what a 7 means */
.gn-p-completed .gnc-col__bar--low { background: #f3c9cd; }
.gn-p-completed .gnc-col__bar--mid { background: $gn-indigo-soft; }
.gn-p-completed .gnc-col__bar--high { background: $gn-sage; }

.gn-p-completed .gnc-col__n {
  margin-top: 7px;
  font-size: 11.5px;
  text-align: center;
  color: $gn-muted-2;
}

.gn-p-completed .gnc-spread__key {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  margin: 12px 0 0;
  font-size: 12px;
  color: $gn-muted;
}


/* =========================================================
   FILTERS
   ========================================================= */

.gn-p-completed .gnc-bar {
  padding: 16px 20px;
  margin-bottom: 20px;
}

.gn-p-completed .gnc-bar__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px 20px;
}

.gn-p-completed .gnc-bar__row--sub {
  justify-content: flex-start;
  gap: 10px 22px;
  padding-top: 14px;
  margin-top: 14px;
  border-top: 1px solid $gn-line-soft;
}

.gn-p-completed .gnc-find {
  position: relative;
  display: flex;
  align-items: center;
  width: 330px;
  max-width: 100%;
  margin: 0;
}

.gn-p-completed .gnc-find input {
  width: 100%;
  height: 38px;
  padding: 0 34px 0 36px;
  border: 1px solid $gn-line;
  border-radius: 9px;
  background: $gn-card;
  font-family: inherit;
  font-size: 13px;
  color: $gn-ink;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.gn-p-completed .gnc-find input:focus {
  outline: 0;
  border-color: $gn-indigo-soft;
  box-shadow: 0 0 0 3px rgba(68, 87, 201, 0.10);
}

.gn-p-completed .gnc-find input::placeholder { color: $gn-muted-2; }

.gn-p-completed .gnc-find__ico {
  position: absolute;
  left: 14px;
  font-size: 12px;
  color: $gn-muted-2;
  pointer-events: none;
}

.gn-p-completed .gnc-find__x {
  position: absolute;
  right: 10px;
  width: 20px;
  height: 20px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: $gn-muted-2;
  font-size: 17px;
  line-height: 1;
  cursor: pointer;
  transition: color 0.2s ease;
}

.gn-p-completed .gnc-find__x:hover { color: $gn-ink; }

/* words with a count, not five filled pills. Five filled pills
   in a row is five things competing to be pressed, and only
   one of them is ever the current filter. */
.gn-p-completed .gnc-chips {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px;
}

.gn-p-completed .gnc-chip {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  padding: 7px 11px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  font-family: inherit;
  font-size: 12.5px;
  font-weight: 500;
  color: $gn-ink-2;
  cursor: pointer;
  transition: background 0.18s ease, color 0.18s ease;
}

.gn-p-completed .gnc-chip:hover {
  background: #f4f6fa;
  color: $gn-ink;
}

.gn-p-completed .gnc-chip.is-on {
  background: $gn-indigo;
  color: #ffffff;
}

.gn-p-completed .gnc-chip__n {
  font-size: 11.5px;
  color: $gn-muted-2;
}

.gn-p-completed .gnc-chip.is-on .gnc-chip__n { color: rgba(255, 255, 255, 0.72); }

/* a native select. A bespoke dropdown has to reimplement
   keyboard handling, typeahead and the mobile picker, and does
   none of them as well as the browser already does. */
.gn-p-completed .gnc-pick {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  min-width: 0;
  font-weight: 400;
}

.gn-p-completed .gnc-pick__l {
  font-size: 12px;
  color: $gn-muted;
  white-space: nowrap;
}

.gn-p-completed .gnc-pick select {
  height: 36px;
  max-width: 210px;
  padding: 0 10px;
  border: 1px solid $gn-line;
  border-radius: 9px;
  background: $gn-card;
  font-family: inherit;
  font-size: 12.5px;
  color: $gn-ink;
  cursor: pointer;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.gn-p-completed .gnc-pick select:focus {
  outline: 0;
  border-color: $gn-indigo-soft;
  box-shadow: 0 0 0 3px rgba(68, 87, 201, 0.10);
}

/* sort is a different kind of control from the two filters
   beside it, and the gap says so without needing a divider */
.gn-p-completed .gnc-pick--sort { margin-left: auto; }

.gn-p-completed .gnc-reset {
  padding: 0;
  border: 0;
  background: transparent;
  font-family: inherit;
  font-size: 12.5px;
  font-weight: 500;
  color: $gn-indigo;
  cursor: pointer;
}

.gn-p-completed .gnc-reset:hover { text-decoration: underline; }


/* =========================================================
   THE ROW
   ========================================================= */

.gn-p-completed .gnc-sub {
  display: block;
  margin-top: 4px;
  font-size: 11.5px;
  font-weight: 400;
  color: $gn-muted;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* said rather than left blank, so nobody wonders whether it
   failed to load */
.gn-p-completed .gnc-sub--none {
  font-style: italic;
  color: $gn-muted-2;
}

/* one treatment for every decision type. The label already
   says which decision it was, and colouring Awarded green and
   Rejected red turns a record into an opinion. */
.gn-p-completed .gnc-dec {
  font-size: 13px;
  color: $gn-ink-2;
}

.gn-p-completed .gnc-score {
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.3px;
  color: $gn-ink;
  white-space: nowrap;
}

.gn-p-completed .gnc-score--high { color: #178a5e; }
.gn-p-completed .gnc-score--mid { color: $gn-indigo; }
.gn-p-completed .gnc-score--low { color: #cf4351; }

/* the denominator, always */
.gn-p-completed .gnc-score__d {
  font-size: 11px;
  font-weight: 400;
  color: $gn-muted-2;
}

.gn-p-completed .gnc-meter {
  display: block;
  width: 64px;
  height: 4px;
  margin-top: 6px;
  border-radius: 999px;
  background: #edf0f6;
  overflow: hidden;
}

.gn-p-completed .gnc-meter__fill {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: $gn-indigo-soft;
  transition: width 0.4s ease;
}

.gn-p-completed .gnc-meter__fill--high { background: $gn-sage; }
.gn-p-completed .gnc-meter__fill--mid { background: $gn-indigo-soft; }
.gn-p-completed .gnc-meter__fill--low { background: #f3c9cd; }


/* =========================================================
   PAGER
   ========================================================= */

.gn-p-completed .gnc-pager {
  flex-wrap: wrap;
  gap: 12px 20px;
}

.gn-p-completed .gnc-pager__go {
  display: flex;
  align-items: center;
  gap: 4px;
}

.gn-p-completed .gnc-pg {
  min-width: 32px;
  height: 32px;
  padding: 0 10px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  font-family: inherit;
  font-size: 12.5px;
  color: $gn-ink-2;
  cursor: pointer;
  transition: background 0.18s ease, color 0.18s ease;
}

.gn-p-completed .gnc-pg:hover {
  background: #f4f6fa;
  color: $gn-ink;
}

.gn-p-completed .gnc-pg.is-on {
  background: $gn-indigo;
  color: #ffffff;
  font-weight: 500;
}

/* Previous and Next carry words rather than arrows. At the
   foot of a table the reader is scanning text, and a word
   needs no legend. */
.gn-p-completed .gnc-pg--step {
  padding: 0 12px;
  color: $gn-muted;
}

.gn-p-completed .gnc-pg--step:hover { color: $gn-ink; }

.gn-p-completed .gnc-pg.is-gap {
  min-width: 18px;
  padding: 0;
  background: transparent;
  color: $gn-muted-2;
  cursor: default;
}

.gn-p-completed .gnc-pg:disabled {
  opacity: 0.35;
  background: transparent;
  cursor: default;
}

.gn-p-completed .gnc-solo { margin-bottom: 20px; }


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1180px) {
  .gn-p-completed .gn-table__head,
.gn-p-completed .gn-table__row {
    grid-template-columns: 1.3fr 1.2fr 1fr 0.9fr 1fr 0.7fr;
    gap: 10px;
    padding: 0 18px;
  }

  .gn-p-completed .gnc-sum { gap: 24px; }

  .gn-p-completed .gnc-fig { padding: 2px 18px; }
}

@media (max-width: 900px) {
  .gn-p-completed .gn-dash { padding: 20px 16px 36px; }

  .gn-p-completed .gn-head {
    flex-direction: column;
    align-items: stretch;
  }

  .gn-p-completed .gn-head__right { flex-wrap: wrap; }

  .gn-p-completed .gn-table__head { display: none; }

  .gn-p-completed .gn-table__row {
    grid-template-columns: 1fr;
    gap: 8px;
    padding: 16px 20px;
  }

  .gn-p-completed .gn-table__row .gn-cell::before {
    content: attr(data-label);
    display: block;
    margin-bottom: 4px;
    font-size: 10.5px;
    letter-spacing: 0.6px;
    text-transform: uppercase;
    color: $gn-muted-2;
  }

  .gn-p-completed .gn-btn { width: 100%; }

  .gn-p-completed .gnc-sum {
    flex-direction: column;
    gap: 22px;
  }

  .gn-p-completed .gnc-figs { width: 100%; }

  .gn-p-completed .gnc-fig {
    flex: 1;
    padding: 2px 14px;
  }

  .gn-p-completed .gnc-spread { width: 100%; }

  .gn-p-completed .gnc-bar__row,
.gn-p-completed .gnc-bar__row--sub {
    align-items: stretch;
    flex-direction: column;
  }

  .gn-p-completed .gnc-find { width: 100%; }

  .gn-p-completed .gnc-chips {
    flex-wrap: nowrap;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    padding-bottom: 2px;
  }

  .gn-p-completed .gnc-chip { flex-shrink: 0; }

  .gn-p-completed .gnc-pick {
    justify-content: space-between;
    width: 100%;
  }

  .gn-p-completed .gnc-pick select {
    flex: 1;
    max-width: none;
  }

  .gn-p-completed .gnc-pick--sort { margin-left: 0; }

  .gn-p-completed .gnc-reset { align-self: flex-start; }
}

@media (max-width: 620px) {
  .gn-p-completed .gn-head__title { font-size: 25px; }

  .gn-p-completed .gnc-fig__n { font-size: 23px; }

  .gn-p-completed .gnc-fig__of { display: block; }

  /* ten columns across 320px is 26px each. The distribution
     stays readable because it carries no labels of its own
     beyond the numbers under it. */
  .gn-p-completed .gnc-spread__grid { gap: 3px; }

  .gn-p-completed .gnc-pager {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (prefers-reduced-motion: reduce) {
  .gn-p-completed .gn-dash * { transition: none; }
}

sp_widget.script:
(function () {

  /* =========================================================
     GATENOW · COMPLETED REVIEWS
     Service Portal widget · Server script

     Page: review_completed

     The logic below is the uploaded widget's, unchanged. Same
     query, same OR block, same overdue and due-soon
     thresholds, same per-row fields, same stats counters, same
     save_review handler and its group check. Only the
     whitespace is tidied and one line is added for the rail,
     which the page shell needs and which reads nothing.

     WHAT THE QUERY SAYS

       review_group IN my groups AND status is in progress
       OR  status is completed AND reviewer CONTAINS my group

     So the page carries the work in front of this reviewer's
     panels plus the completed records their panels were on.
     This is the same script the review_applicants page runs,
     to the character. That page's client drops the completed
     rows from its list; this page's client keeps only those.
     One query serves both, which is why the two pages can
     never disagree about a review.

     Keeping them identical is deliberate. Two scripts that are
     meant to return the same rows will drift the first time
     one of them is edited, and the drift shows up as a review
     that appears on one page and not the other.
     ========================================================= */

  data.announcements = [];

  /* ── Current user ────────────────────────────────────────── */

  var userRecord = new GlideRecordSecure('sys_user');

  if (userRecord.get(gs.getUserID())) {

    data.currentUser = {
      sys_id    : userRecord.getUniqueValue(),
      name      : userRecord.getDisplayValue('name') || 'Reviewer',
      first_name: userRecord.getValue('first_name') || '',
      last_name : userRecord.getValue('last_name') || '',
      email     : userRecord.getValue('email') || '',
      title     : userRecord.getValue('title') || 'Grant Reviewer',
      initials  : (userRecord.getValue('first_name') || 'R').charAt(0).toUpperCase() +
                  (userRecord.getValue('last_name') || '').charAt(0).toUpperCase()
    };

  } else {

    data.currentUser = {
      sys_id    : '',
      name      : 'Guest',
      first_name: '',
      last_name : '',
      email     : '',
      title     : '',
      initials  : 'G'
    };
  }

  data.logoutUrl   = '/login.do?logout=true';
  data.profilePage = '?id=user_profile';
  data.canRead     = true;
  data.reviews     = [];

  /* The one addition: the rail is its own widget and this page
     hosts it. It reads nothing and changes nothing. */
  data.sideBar = $sp.getWidget(
    (options.sidebar_widget || 'review_sidebar').toString()
  );

  /* ── Property-driven URLs ────────────────────────────────── */

  data.svgNS      = gs.getProperty('x_enno_gatenow.svg_namespace', 'http://www.w3.org/2000/svg');
  data.chartJsUrl = gs.getProperty('x_enno_gatenow.chartjs_cdn_url', 'https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js');

  /* ── Full stats object ───────────────────────────────────── */

  data.stats = {
    total     : 0,
    inProgress: 0,
    completed : 0,
    escalated : 0,
    declined  : 0,
    pending   : 0,
    overdue   : 0,
    dueSoon   : 0
  };

  var userId = gs.getUserID();
  var today  = new GlideDateTime();

  /* ── Groups ──────────────────────────────────────────────── */

  var groups = [];

  var groupMembershipGr = new GlideRecordSecure('sys_user_grmember');
  groupMembershipGr.addQuery('user', userId);
  groupMembershipGr.query();

  while (groupMembershipGr.next()) {
    groups.push(groupMembershipGr.getValue('group'));
  }

  if (groups.length === 0) {
    return;
  }

  /* ── Query reviews ───────────────────────────────────────── */
  var grantReviewGr = new GlideRecordSecure('x_enno_gatenow_grant_review');

  /* My group holds it now, OR one of my groups is on its
     reviewer list. Every addOrCondition hangs off the same
     QueryCondition, so the whole thing stays one bracketed OR
     instead of leaking an AND onto the end.

     No status filter here on purpose: review_applicants drops
     the completed rows in its client and review_completed
     keeps only those, so filtering on the server would mean
     one of the two pages asking for rows the other had already
     excluded. */
  var qc = grantReviewGr.addQuery('review_group', 'IN', groups.join(','));

  for (var i = 0; i < groups.length; i++) {
    qc.addOrCondition('reviewer', 'CONTAINS', groups[i]);
  }

  grantReviewGr.orderBy('number');
  grantReviewGr.query();

  while (grantReviewGr.next()) {

    var status = grantReviewGr.getDisplayValue('status');

    var deadlineVal  = grantReviewGr.getValue('review_deadline') || '';
    var deadlineDisp = deadlineVal ? grantReviewGr.getDisplayValue('review_deadline') : '';

    var isOverdue = false;
    var isDueSoon = false;

    if (deadlineVal) {

      var dl       = new GlideDateTime(deadlineVal);
      var diffMs   = dl.getNumericValue() - today.getNumericValue();
      var diffDays = diffMs / (1000 * 60 * 60 * 24);

      if (diffDays < 0 && status !== 'Review completed' && status !== 'Declined by Reviewer') {
        isOverdue = true;
      } else if (diffDays >= 0 && diffDays <= 3 && status !== 'Review completed' && status !== 'Declined by Reviewer') {
        isDueSoon = true;
      }
    }

    var reviewerDisplay = grantReviewGr.getDisplayValue('reviewer') || '';

    var programName     = '';
    var programCategory = '';
    var programNumber   = '';
    var programSysId    = grantReviewGr.getValue('program');

    if (programSysId) {
      var programGr = new GlideRecordSecure('x_enno_gatenow_grant_program');
      if (programGr.get(programSysId)) {
        programName     = programGr.getDisplayValue('program_name') || '';
        programCategory = programGr.getDisplayValue('category') || '';
        programNumber   = programGr.getValue('number') || '';
      }
    }

    var applicantName   = '';
    var applicantNumber = '';
    var applicantSysId  = grantReviewGr.getValue('applicant');

    if (applicantSysId) {
      var applicantGr = new GlideRecordSecure('x_enno_gatenow_service_applicants');
      if (applicantGr.get(applicantSysId)) {
        applicantName   = ((applicantGr.getValue('first_name') || '') + ' ' +
                           (applicantGr.getValue('last_name') || '')).trim();
        applicantNumber = applicantGr.getValue('number') || '';
      }
    }

    /* Update stats */

    data.stats.total++;

    if (status === 'Review in progress')
      data.stats.inProgress++;
    else if (status === 'Review completed')
      data.stats.completed++;
    else if (status === 'Escalated')
      data.stats.escalated++;
    else if (status === 'Declined by Reviewer')
      data.stats.declined++;
    else if (status === 'Review pending')
      data.stats.pending++;

    if (isOverdue)
      data.stats.overdue++;

    if (isDueSoon)
      data.stats.dueSoon++;

    /* Push review data */

    data.reviews.push({
      sys_id          : grantReviewGr.getUniqueValue(),
      number          : grantReviewGr.getValue('number') || '',
      status          : status,
      review_group    : grantReviewGr.getDisplayValue('review_group') || '',
      reviewer        : reviewerDisplay,
      score           : grantReviewGr.getValue('score') || '',
      applicant       : applicantName,
      applicant_number: applicantNumber,
      program         : programName,
      program_number  : programNumber,
      program_category: programCategory,
      decision_type   : grantReviewGr.getDisplayValue('decision_type') || '',
      review_deadline : deadlineDisp,
      deadline_raw    : deadlineVal,
      is_overdue      : isOverdue,
      is_due_soon     : isDueSoon
    });
  }

  /* ── Save review ─────────────────────────────────────────── */

  if (input && input.action === 'save_review' && input.review_sys_id) {

    var reviewId = String(input.review_sys_id);
    var form     = input.form || {};
    var grUpdate = new GlideRecordSecure('x_enno_gatenow_grant_review');

    if (grUpdate.get(reviewId)) {

      if (groups.indexOf(grUpdate.getValue('review_group')) === -1) {
        data.success = false;
        data.error   = 'Not allowed.';
        return;
      }

      if (form.decision_type)
        grUpdate.setValue('decision_type', form.decision_type);

      if (form.status)
        grUpdate.setValue('status', form.status);

      if (!gs.nil(form.score))
        grUpdate.setValue('score', form.score);

      if (!gs.nil(form.review_notes))
        grUpdate.setValue('work_notes', form.review_notes);

      grUpdate.update();
      data.success = true;

    } else {
      data.success = false;
      data.error   = 'Not found.';
    }
  }

})();
